package com.drophistory;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.lang.reflect.Type;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Reads and writes drop history to a local JSON file.
 * Stored at ~/.runelite/drop-history/drops.json.
 * File storage avoids the RuneLite config service size limit.
 *
 * Writes are expensive (the whole dataset is serialized), so they never run
 * on the game thread. {@link #recordDrop} updates the in-memory cache
 * synchronously and schedules a debounced flush on a background thread;
 * disk writes are coalesced and performed atomically via a temp file.
 */
@Slf4j
@Singleton
public class DropHistoryManager
{
    private static final Type DATA_TYPE = new TypeToken<Map<String, List<DropRecord>>>(){}.getType();
    private static final File DATA_FILE = new File(RuneLite.RUNELITE_DIR, "drop-history/drops.json");
    private static final File TEMP_FILE = new File(RuneLite.RUNELITE_DIR, "drop-history/drops.json.tmp");

    /** Coalesce rapid changes (e.g. a multi-item drop) into one disk write. */
    private static final long SAVE_DELAY_MS = 3000;

    @Inject
    private Gson gson;

    @Inject
    private ScheduledExecutorService executor;

    /** In-memory cache to avoid deserializing on every render frame. Guarded by {@code this}. */
    private Map<String, List<DropRecord>> cache = null;

    /** Pending debounced flush, if any. Guarded by {@code this}. */
    private ScheduledFuture<?> pendingSave;

    /** Serializes disk writes so a background flush and a shutdown flush never interleave. */
    private final Object diskLock = new Object();

    public synchronized void recordDrop(String itemName, int killCount, String source)
    {
        loadData().computeIfAbsent(normalize(itemName), k -> new ArrayList<>())
            .add(new DropRecord(killCount, source, System.currentTimeMillis()));
        scheduleSave();
    }

    /**
     * Merges a pre-built map of drops into the stored data. Used by the
     * importers at startup; flushed synchronously so the data is durable
     * before an importer writes its "done" flag.
     */
    public synchronized void bulkMerge(Map<String, List<DropRecord>> incoming)
    {
        Map<String, List<DropRecord>> data = loadData();
        for (Map.Entry<String, List<DropRecord>> entry : incoming.entrySet())
        {
            String key = normalize(entry.getKey());
            List<DropRecord> existing = data.computeIfAbsent(key, k -> new ArrayList<>());
            for (DropRecord record : entry.getValue())
            {
                boolean dup = existing.stream().anyMatch(
                    r -> r.getKillCount() == record.getKillCount()
                        && record.getSource().equalsIgnoreCase(r.getSource())
                );
                if (!dup)
                {
                    existing.add(record);
                }
            }
        }
        flushNow();
    }

    public synchronized List<DropRecord> getDrops(String itemName)
    {
        return loadData().getOrDefault(normalize(itemName), new ArrayList<>());
    }

    /**
     * Fills in an estimated kill count on a record that previously had an
     * unknown KC, identified by item and timestamp. Called from an HTTP
     * callback thread.
     */
    public synchronized void applyEstimate(String itemName, long timestamp, int killCount, String source)
    {
        List<DropRecord> records = loadData().get(normalize(itemName));
        if (records == null)
        {
            return;
        }
        for (DropRecord record : records)
        {
            if (record.getTimestamp() == timestamp && record.getKillCount() == -1)
            {
                record.setKillCount(killCount);
                record.setSource(source);
                record.setEstimated(true);
                scheduleSave();
                return;
            }
        }
    }

    private String normalize(String name)
    {
        return name == null ? "" : name.toLowerCase().trim();
    }

    public synchronized void invalidateCache()
    {
        cache = null;
    }

    /** Persists any pending changes immediately. Call on plugin shutdown. */
    public void flushNow()
    {
        String json;
        synchronized (this)
        {
            if (pendingSave != null)
            {
                pendingSave.cancel(false);
                pendingSave = null;
            }
            if (cache == null)
            {
                return;
            }
            json = gson.toJson(cache);
        }
        writeToDisk(json);
    }

    // -------------------------------------------------------------------------

    /** Schedules a single debounced flush. Must hold {@code this}. */
    private void scheduleSave()
    {
        if (pendingSave != null && !pendingSave.isDone())
        {
            return;
        }
        pendingSave = executor.schedule(this::flush, SAVE_DELAY_MS, TimeUnit.MILLISECONDS);
    }

    /** Background flush: snapshot under lock, write off-lock. */
    private void flush()
    {
        String json;
        synchronized (this)
        {
            pendingSave = null;
            if (cache == null)
            {
                return;
            }
            json = gson.toJson(cache);
        }
        writeToDisk(json);
    }

    private Map<String, List<DropRecord>> loadData()
    {
        if (cache != null)
        {
            return cache;
        }
        if (!DATA_FILE.exists())
        {
            cache = new HashMap<>();
            return cache;
        }
        try (FileReader reader = new FileReader(DATA_FILE))
        {
            cache = gson.fromJson(reader, DATA_TYPE);
            if (cache == null) cache = new HashMap<>();
        }
        catch (Exception e)
        {
            log.warn("Failed to load drop history data", e);
            cache = new HashMap<>();
        }
        return cache;
    }

    private void writeToDisk(String json)
    {
        synchronized (diskLock)
        {
            DATA_FILE.getParentFile().mkdirs();
            try (FileWriter writer = new FileWriter(TEMP_FILE))
            {
                writer.write(json);
            }
            catch (IOException e)
            {
                log.error("Failed to write drop history data", e);
                return;
            }
            try
            {
                Files.move(TEMP_FILE.toPath(), DATA_FILE.toPath(),
                    StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (IOException e)
            {
                // Atomic move not supported on some setups; fall back to a plain replace.
                try
                {
                    Files.move(TEMP_FILE.toPath(), DATA_FILE.toPath(), StandardCopyOption.REPLACE_EXISTING);
                }
                catch (IOException e2)
                {
                    log.error("Failed to persist drop history data", e2);
                }
            }
        }
    }
}

package com.drophistory;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A single recorded drop of an item.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class DropRecord
{
    /** Kill count at time of drop. -1 if KC was unknown. */
    private int killCount;

    /** The boss or source name (e.g. "Zulrah"). */
    private String source;

    /** Unix timestamp (ms) of when the drop was received. */
    private long timestamp;

    /**
     * True when the kill count was estimated (e.g. interpolated from
     * Wise Old Man snapshots) rather than observed directly.
     * Absent in older saved data, which Gson deserializes as false.
     */
    private boolean estimated;

    public DropRecord(int killCount, String source, long timestamp)
    {
        this(killCount, source, timestamp, false);
    }
}

package com.drophistory;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.RuneScapeProfileType;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.File;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * One-time importer that backfills drop history from RuneLite's screenshot
 * folders.
 *
 * The core Screenshot plugin saves "Collection log (Item name).png" by
 * default whenever a collection log entry is completed, which gives us the
 * item and the date it was obtained. If the player also had boss kill
 * screenshots enabled, files like "Vorkath(847).png" taken at the same
 * moment give us the exact kill count. Otherwise the record is imported
 * with an unknown KC, which the Wise Old Man estimator may fill in later.
 *
 * Like LootTrackerImporter, this only marks itself complete after importing
 * at least one record, so it retries on startup until data appears.
 */
@Slf4j
@Singleton
public class ScreenshotImporter
{
    private static final File IMPORTED_FLAG = new File(RuneLite.RUNELITE_DIR, "drop-history/screenshots-imported.flag");

    // "Collection log (Dragon warhammer).png" with an optional trailing timestamp
    private static final Pattern COLLECTION_LOG_FILE =
        Pattern.compile("^Collection log \\((.+)\\)(?: (\\d{4}-\\d{2}-\\d{2}_\\d{2}-\\d{2}-\\d{2}))?\\.png$");

    // "Vorkath(847).png" with an optional trailing timestamp
    private static final Pattern BOSS_KILL_FILE =
        Pattern.compile("^(.+?)\\((\\d+)\\)(?: (\\d{4}-\\d{2}-\\d{2}_\\d{2}-\\d{2}-\\d{2}))?\\.png$");

    private static final SimpleDateFormat FILE_TS_FMT = new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss");

    /** A boss kill screenshot within this window of a collection log screenshot is the same kill. */
    private static final long KILL_MATCH_WINDOW_MS = 2 * 60_000L;

    /** Skip a screenshot record when an existing record for the item is within this window. */
    private static final long DUPLICATE_WINDOW_MS = 10 * 60_000L;

    @Inject private DropHistoryManager manager;

    private static class BossKillShot
    {
        final String boss;
        final int killCount;
        final long timestamp;

        BossKillShot(String boss, int killCount, long timestamp)
        {
            this.boss = boss;
            this.killCount = killCount;
            this.timestamp = timestamp;
        }
    }

    public void runIfNeeded()
    {
        if (IMPORTED_FLAG.exists())
        {
            log.debug("Screenshot import already done, skipping");
            return;
        }

        File screenshotsDir = new File(RuneLite.RUNELITE_DIR, "screenshots");
        if (!screenshotsDir.exists())
        {
            log.info("No screenshots directory found at {} — screenshot import skipped, will retry next startup", screenshotsDir);
            return;
        }

        // Screenshots live either directly under screenshots/ (legacy) or in
        // one subdirectory per player. Match boss kills to collection log
        // entries within the same directory only. Directories for limited
        // time modes (leagues, deadman, ...) carry a "-<Profile Type>"
        // suffix and are skipped — only main game drops are imported.
        List<File> playerDirs = new ArrayList<>();
        playerDirs.add(screenshotsDir);
        File[] subDirs = screenshotsDir.listFiles(File::isDirectory);
        if (subDirs != null)
        {
            for (File d : subDirs)
            {
                if (!isSpecialModeDir(d.getName()))
                {
                    playerDirs.add(d);
                }
            }
        }

        Map<String, List<DropRecord>> incoming = new HashMap<>();
        int totalRecords = 0;

        for (File playerDir : playerDirs)
        {
            totalRecords += importPlayerDir(playerDir, incoming);
        }

        if (totalRecords == 0)
        {
            log.info("No importable collection log screenshots found — will retry next startup");
            return;
        }

        manager.bulkMerge(incoming);
        log.info("Screenshot import complete — {} drop records imported", totalRecords);
        markDone();
    }

    private int importPlayerDir(File playerDir, Map<String, List<DropRecord>> incoming)
    {
        File[] collectionShots = listPngs(new File(playerDir, "Collection Log"));
        if (collectionShots == null || collectionShots.length == 0)
        {
            return 0;
        }

        List<BossKillShot> bossKills = parseBossKills(listPngs(new File(playerDir, "Boss Kills")));

        int count = 0;
        for (File shot : collectionShots)
        {
            Matcher m = COLLECTION_LOG_FILE.matcher(shot.getName());
            if (!m.matches())
            {
                continue;
            }

            String itemName = m.group(1).trim();
            long timestamp = fileTimestamp(shot, m.group(2));

            if (hasNearbyRecord(manager.getDrops(itemName), timestamp)
                || hasNearbyRecord(incoming.get(itemName.toLowerCase().trim()), timestamp))
            {
                continue;
            }

            BossKillShot kill = findMatchingKill(bossKills, timestamp);
            DropRecord record = kill != null
                ? new DropRecord(kill.killCount, kill.boss, timestamp)
                : new DropRecord(-1, "Unknown", timestamp);

            incoming.computeIfAbsent(itemName.toLowerCase().trim(), k -> new ArrayList<>()).add(record);
            count++;
        }
        return count;
    }

    /**
     * True when a player screenshot directory belongs to a limited time
     * game mode. The Screenshot plugin appends "-<Profile Type>" to the
     * player name for non-standard worlds, e.g. "name-Deadman" or
     * "name-Trailblazer League"; the suffixes are derived from the client's
     * own profile type enum so new league names are covered automatically.
     */
    static boolean isSpecialModeDir(String dirName)
    {
        String lower = dirName.toLowerCase();
        for (RuneScapeProfileType type : RuneScapeProfileType.values())
        {
            if (type == RuneScapeProfileType.STANDARD)
            {
                continue;
            }
            String suffix = "-" + type.name().toLowerCase().replace('_', ' ');
            if (lower.endsWith(suffix))
            {
                return true;
            }
        }
        return false;
    }

    private static File[] listPngs(File dir)
    {
        if (!dir.isDirectory())
        {
            return null;
        }
        return dir.listFiles(f -> f.isFile() && f.getName().endsWith(".png"));
    }

    private static List<BossKillShot> parseBossKills(File[] files)
    {
        List<BossKillShot> kills = new ArrayList<>();
        if (files == null)
        {
            return kills;
        }
        for (File f : files)
        {
            Matcher m = BOSS_KILL_FILE.matcher(f.getName());
            if (!m.matches())
            {
                continue;
            }
            try
            {
                kills.add(new BossKillShot(m.group(1).trim(), Integer.parseInt(m.group(2)), fileTimestamp(f, m.group(3))));
            }
            catch (NumberFormatException e)
            {
                // kill count too large to be real; skip
            }
        }
        return kills;
    }

    private static BossKillShot findMatchingKill(List<BossKillShot> kills, long timestamp)
    {
        BossKillShot best = null;
        long bestDelta = KILL_MATCH_WINDOW_MS + 1;
        for (BossKillShot kill : kills)
        {
            long delta = Math.abs(kill.timestamp - timestamp);
            if (delta <= KILL_MATCH_WINDOW_MS && delta < bestDelta)
            {
                best = kill;
                bestDelta = delta;
            }
        }
        return best;
    }

    private static boolean hasNearbyRecord(List<DropRecord> records, long timestamp)
    {
        if (records == null)
        {
            return false;
        }
        return records.stream().anyMatch(r -> Math.abs(r.getTimestamp() - timestamp) <= DUPLICATE_WINDOW_MS);
    }

    /** Prefer the timestamp embedded in the filename; fall back to file mtime. */
    private static long fileTimestamp(File file, String nameTimestamp)
    {
        if (nameTimestamp != null)
        {
            try
            {
                return FILE_TS_FMT.parse(nameTimestamp).getTime();
            }
            catch (ParseException e)
            {
                // fall through to mtime
            }
        }
        return file.lastModified();
    }

    private void markDone()
    {
        IMPORTED_FLAG.getParentFile().mkdirs();
        try
        {
            if (!IMPORTED_FLAG.createNewFile())
            {
                log.debug("Import flag already existed");
            }
        }
        catch (java.io.IOException e)
        {
            log.warn("Could not write screenshot import flag", e);
        }
    }
}

package com.drophistory;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.util.Collection;

@Slf4j
@PluginDescriptor(
    name = "Drop History",
    description = "Tracks what KC you received each collection log item at. Hover items in your collection log to see the full history.",
    tags = {"collection log", "drop", "kc", "kill count", "loot", "tracker"}
)
public class DropHistoryPlugin extends Plugin
{
    @Inject private DropHistoryConfig config;
    @Inject private DropHistoryManager manager;
    @Inject private DropHistoryOverlay overlay;
    @Inject private KillCountTracker kcTracker;
    @Inject private LootTrackerImporter lootTrackerImporter;
    @Inject private ScreenshotImporter screenshotImporter;
    @Inject private OverlayManager overlayManager;
    @Inject private ItemManager itemManager;
    @Inject private EventBus eventBus;

    @Override
    protected void startUp()
    {
        manager.invalidateCache();
        overlayManager.add(overlay);
        eventBus.register(kcTracker);
        // Order matters: the loot tracker import provides exact KCs, so it
        // runs first and the screenshot import dedupes against its records.
        lootTrackerImporter.runIfNeeded();
        screenshotImporter.runIfNeeded();
        log.debug("Drop History started");
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        eventBus.unregister(kcTracker);
        manager.flushNow();
        log.debug("Drop History stopped");
    }

    @Provides
    DropHistoryConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(DropHistoryConfig.class);
    }

    /**
     * Fires when loot is received from an NPC kill.
     * Covers most PvM content: bosses, slayer, etc.
     */
    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        String source = event.getNpc().getName();
        if (source == null)
        {
            return;
        }

        int kc = kcTracker.getKillCount(source);
        Collection<ItemStack> items = event.getItems();

        for (ItemStack stack : items)
        {
            String itemName = itemManager.getItemComposition(stack.getId()).getName();
            if (itemName == null || itemName.isEmpty())
            {
                continue;
            }
            log.debug("Recording drop: {} from {} at KC {}", itemName, source, kc);
            manager.recordDrop(itemName, kc, source);
        }
    }

    /**
     * Invalidate cache on login so config service changes from other devices are picked up.
     */
    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            manager.invalidateCache();
        }
    }
}

package com.drophistory;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(DropHistoryConfig.GROUP)
public interface DropHistoryConfig extends Config
{
    String GROUP = "drophistory";

    @ConfigItem(
        keyName = "showTooltip",
        name = "Show KC tooltip on collection log",
        description = "When hovering a collection log item, show which KC you received each drop"
    )
    default boolean showTooltip()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showTimestamp",
        name = "Show date in tooltip",
        description = "Include the date alongside the KC in the tooltip"
    )
    default boolean showTimestamp()
    {
        return false;
    }

    @Range(min = 1)
    @ConfigItem(
        keyName = "maxDropsShown",
        name = "Max drops listed per item",
        description = "Items with more recorded drops than this show a short summary instead of every drop. Keeps the tooltip usable for items that drop in bulk, like Demon tears."
    )
    default int maxDropsShown()
    {
        return 25;
    }

    @ConfigItem(
        keyName = "womEstimates",
        name = "Estimate KCs via Wise Old Man",
        description = "For imported drops with an unknown KC, look up your historical boss KC on wiseoldman.net and show an estimate. Sends your display name to the Wise Old Man API.",
        warning = "This plugin submits your IP address to a 3rd-party server not controlled or verified by Runelite developers"
    )
    default boolean womEstimates()
    {
        return false;
    }
}

package com.drophistory;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * One-time importer that reads RuneLite's loot tracker .log files and
 * backfills DropHistory with historical KC data.
 *
 * Builds the full dataset in memory first, then flushes in a single file write
 * to avoid race conditions with invalidateCache() during login.
 *
 * The import is only marked complete once at least one record has been
 * imported; if no local loot tracker data exists yet, it retries on every
 * startup so data added later is still picked up.
 */
@Slf4j
@Singleton
public class LootTrackerImporter
{
    private static final File IMPORTED_FLAG = new File(RuneLite.RUNELITE_DIR, "drop-history/imported.flag");
    private static final SimpleDateFormat LOG_DATE_FMT =
        new SimpleDateFormat("MMM d, yyyy, h:mm:ss a");

    @Inject private DropHistoryManager manager;

    public void runIfNeeded()
    {
        if (IMPORTED_FLAG.exists())
        {
            log.debug("Loot tracker import already done, skipping");
            return;
        }

        File lootsDir = new File(RuneLite.RUNELITE_DIR, "loots");
        File[] profiles = lootsDir.exists()
            ? lootsDir.listFiles(f -> f.isDirectory() && f.getName().matches("\\d+"))
            : null;
        if (profiles == null || profiles.length == 0)
        {
            // Don't mark done — the loot tracker may write data later,
            // so check again on the next startup.
            log.info("No local loot tracker data found at {} — historical import skipped, will retry next startup", lootsDir);
            return;
        }

        // Build entire import in memory — no file I/O until the very end.
        Map<String, List<DropRecord>> incoming = new HashMap<>();
        int totalRecords = 0;

        for (File profile : profiles)
        {
            for (String subDir : new String[]{"npc", "event"})
            {
                File dir = new File(profile, subDir);
                if (!dir.exists()) continue;

                File[] logs = dir.listFiles(f -> f.getName().endsWith(".log"));
                if (logs == null) continue;

                for (File logFile : logs)
                {
                    totalRecords += parseLogFile(logFile, incoming);
                }
            }
        }

        if (totalRecords == 0)
        {
            log.info("Loot tracker logs contained no importable drops — will retry next startup");
            return;
        }

        // Single write for all imported data
        manager.bulkMerge(incoming);
        log.info("Loot tracker import complete — {} drop records imported", totalRecords);
        markDone();
    }

    private int parseLogFile(File logFile, Map<String, List<DropRecord>> incoming)
    {
        int count = 0;
        try (BufferedReader reader = new BufferedReader(new FileReader(logFile)))
        {
            String line;
            while ((line = reader.readLine()) != null)
            {
                line = line.trim();
                if (line.isEmpty()) continue;
                try
                {
                    count += parseLine(line, incoming);
                }
                catch (Exception e)
                {
                    log.warn("Failed to parse line in {}: {}", logFile.getName(), e.getMessage());
                }
            }
        }
        catch (IOException e)
        {
            log.warn("Could not read loot log: {}", logFile.getAbsolutePath());
        }
        return count;
    }

    private int parseLine(String line, Map<String, List<DropRecord>> incoming)
    {
        JsonObject obj = new JsonParser().parse(line).getAsJsonObject();

        JsonElement sourceEl = obj.get("name");
        if (sourceEl == null || sourceEl.isJsonNull()) return 0;
        String source = sourceEl.getAsString();

        // Loot tracker records only carry a kill count when the KC chat
        // message was seen; treat missing KC as unknown (-1) rather than
        // discarding the drop entirely.
        JsonElement kcEl = obj.get("killCount");
        int killCount = (kcEl != null && !kcEl.isJsonNull()) ? kcEl.getAsInt() : -1;

        JsonElement dateEl = obj.get("date");
        long timestamp = (dateEl != null && !dateEl.isJsonNull())
            ? parseDate(dateEl.getAsString())
            : System.currentTimeMillis();

        JsonArray drops = obj.getAsJsonArray("drops");
        if (drops == null) return 0;

        int count = 0;
        for (JsonElement el : drops)
        {
            JsonElement itemEl = el.getAsJsonObject().get("name");
            if (itemEl == null || itemEl.isJsonNull()) continue;
            String itemName = itemEl.getAsString();
            if (itemName == null || itemName.isEmpty()) continue;

            String key = itemName.toLowerCase().trim();
            List<DropRecord> records = incoming.computeIfAbsent(key, k -> new ArrayList<>());
            boolean dup = records.stream().anyMatch(
                r -> r.getKillCount() == killCount && source.equalsIgnoreCase(r.getSource())
            );
            if (!dup)
            {
                records.add(new DropRecord(killCount, source, timestamp));
                count++;
            }
        }
        return count;
    }

    private long parseDate(String dateStr)
    {
        try
        {
            return LOG_DATE_FMT.parse(dateStr).getTime();
        }
        catch (ParseException e)
        {
            return System.currentTimeMillis();
        }
    }

    private void markDone()
    {
        IMPORTED_FLAG.getParentFile().mkdirs();
        try
        {
            IMPORTED_FLAG.createNewFile();
        }
        catch (IOException e)
        {
            log.warn("Could not write import flag", e);
        }
    }
}

package com.drophistory;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import java.awt.*;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;

/**
 * Renders a KC history tooltip when hovering an item in the collection log.
 * Uses InterfaceID.Collection.ITEMS_CONTENTS to locate the item grid widget.
 * Each dynamic child of that container is an item slot.
 */
@Slf4j
public class DropHistoryOverlay extends Overlay
{
    private static final SimpleDateFormat DATE_FMT = new SimpleDateFormat("MMM d, yyyy");

    @Inject private Client client;
    @Inject private DropHistoryConfig config;
    @Inject private DropHistoryManager manager;
    @Inject private TooltipManager tooltipManager;
    @Inject private WomKcEstimator estimator;

    @Inject
    public DropHistoryOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showTooltip())
        {
            return null;
        }

        Widget container = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
        if (container == null || container.isHidden())
        {
            return null;
        }

        Widget[] items = container.getDynamicChildren();
        if (items == null)
        {
            return null;
        }

        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null)
        {
            return null;
        }

        for (Widget item : items)
        {
            if (item == null || item.isHidden() || item.getItemId() == -1)
            {
                continue;
            }

            if (!item.getBounds().contains(mouse.getX(), mouse.getY()))
            {
                continue;
            }

            // Resolve item name — strip color tags
            String itemName = item.getName();
            if (itemName == null || itemName.isEmpty())
            {
                itemName = client.getItemDefinition(item.getItemId()).getName();
            }
            itemName = itemName.replaceAll("<[^>]+>", "").trim();

            if (itemName.isEmpty())
            {
                break;
            }

            List<DropRecord> drops = manager.getDrops(itemName);

            StringBuilder sb = new StringBuilder();
            sb.append("<col=ff9040>Drop History: ").append(itemName).append("</col>");

            if (drops.isEmpty())
            {
                sb.append("<br><col=aaaaaa>No drops recorded yet</col>");
            }
            else if (drops.size() > config.maxDropsShown())
            {
                // Bulk items (Demon tears, Tokkul, ...) can have thousands
                // of recorded drops; show a summary instead of every line.
                sb.append("<br><col=aaaaaa>").append(String.format("%,d", drops.size()))
                  .append(" drops recorded</col>");
                int firstKc = drops.stream()
                    .mapToInt(DropRecord::getKillCount)
                    .filter(kc -> kc > 0)
                    .min()
                    .orElse(-1);
                if (firstKc > 0)
                {
                    sb.append("<br><col=ffffff>First at KC ").append(String.format("%,d", firstKc)).append("</col>");
                }
            }
            else
            {
                String pageTitle = collectionLogPageTitle();
                String playerName = client.getLocalPlayer() != null
                    ? client.getLocalPlayer().getName()
                    : null;

                for (DropRecord record : drops)
                {
                    if (record.getKillCount() == -1)
                    {
                        // Kick off an async WOM estimate; no-op after the first call.
                        estimator.requestEstimate(itemName, record, pageTitle, playerName);
                    }

                    sb.append("<br>");
                    if (record.getKillCount() == -1)
                    {
                        sb.append("<col=aaaaaa>KC unknown</col>");
                    }
                    else if (record.isEstimated())
                    {
                        sb.append("<col=ffffff>KC ~").append(String.format("%,d", record.getKillCount())).append("</col>")
                          .append(" <col=aaaaaa>(est.)</col>");
                    }
                    else
                    {
                        sb.append("<col=ffffff>KC ").append(String.format("%,d", record.getKillCount())).append("</col>");
                    }

                    String source = record.getSource();
                    if (source != null && !source.isEmpty() && !"Unknown".equalsIgnoreCase(source))
                    {
                        sb.append(" <col=ff9040>— ").append(source).append("</col>");
                    }

                    // For unknown KCs the date is the only information we
                    // have, so always show it there.
                    if ((config.showTimestamp() || record.getKillCount() == -1) && record.getTimestamp() > 0)
                    {
                        sb.append(" <col=888888>(")
                          .append(DATE_FMT.format(new Date(record.getTimestamp())))
                          .append(")</col>");
                    }
                }
            }

            tooltipManager.add(new Tooltip(sb.toString()));
            break;
        }

        return null;
    }

    /**
     * The title of the currently open collection log page (e.g. "Vorkath"),
     * which identifies the boss for KC estimation. Null when unavailable.
     */
    private String collectionLogPageTitle()
    {
        Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
        if (header == null)
        {
            return null;
        }
        Widget[] children = header.getDynamicChildren();
        if (children == null || children.length == 0 || children[0].getText() == null)
        {
            return null;
        }
        String title = children[0].getText().replaceAll("<[^>]+>", "").trim();
        return title.isEmpty() ? null : title;
    }
}

package com.drophistory;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Watches game chat messages for KC announcements and caches the latest
 * kill count per boss so it's available when a loot event fires.
 *
 * Handles messages like:
 *   "Your Zulrah kill count is: 47."
 *   "Your Chambers of Xeric kill count is: 12."
 *   "Your Theatre of Blood completion count is: 5."
 *   "Your Barrows chest count is: 100."
 */
@Slf4j
@Singleton
public class KillCountTracker
{
    private static final Pattern KC_PATTERN = Pattern.compile(
        "Your (?<boss>.+?) (?:kill count|chest count|completion count) is: (?<kc>[\\d,]+)\\.",
        Pattern.CASE_INSENSITIVE
    );

    private final Map<String, Integer> killCounts = new HashMap<>();

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE
            && event.getType() != ChatMessageType.SPAM)
        {
            return;
        }

        // Strip color tags before matching
        String message = event.getMessage().replaceAll("<[^>]+>", "").trim();

        Matcher m = KC_PATTERN.matcher(message);
        if (m.matches())
        {
            String boss = m.group("boss").trim();
            try
            {
                int kc = Integer.parseInt(m.group("kc").replace(",", ""));
                killCounts.put(normalize(boss), kc);
                log.debug("KC tracked: {} -> {}", boss, kc);
            }
            catch (NumberFormatException e)
            {
                log.warn("Failed to parse KC from: {}", message);
            }
        }
    }

    /**
     * Returns the last known KC for a boss, or -1 if not yet seen.
     */
    public int getKillCount(String bossName)
    {
        return killCounts.getOrDefault(normalize(bossName), -1);
    }

    private String normalize(String name)
    {
        return name.toLowerCase().trim();
    }
}

package com.drophistory;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Estimates the kill count for drops where only the date is known, by
 * interpolating the player's historical boss KC from Wise Old Man snapshots.
 *
 * Requests are made lazily when an unknown-KC record is displayed, at most
 * once per record per session, and successful estimates are persisted so
 * they are never requested again.
 */
@Slf4j
@Singleton
public class WomKcEstimator
{
    private static final String WOM_API_BASE = "https://api.wiseoldman.net/v2";
    private static final String USER_AGENT = "drop-history RuneLite plugin (github.com/markuskkramer/drop-history)";

    /** How far around the drop date to look for KC snapshots. */
    private static final long SNAPSHOT_WINDOW_MS = 180L * 24 * 60 * 60 * 1000;

    /**
     * Collection log page names that don't map to a WOM boss metric by
     * simple normalization.
     */
    private static final Map<String, String> METRIC_ALIASES = new HashMap<>();

    static
    {
        METRIC_ALIASES.put("the nightmare", "nightmare");
        METRIC_ALIASES.put("the mimic", "mimic");
        METRIC_ALIASES.put("the fight caves", "tztok_jad");
        METRIC_ALIASES.put("the inferno", "tzkal_zuk");
        METRIC_ALIASES.put("moons of peril", "lunar_chests");
        METRIC_ALIASES.put("fortis colosseum", "sol_heredit");
        METRIC_ALIASES.put("royal titans", "the_royal_titans");
    }

    private static final Type TIMELINE_TYPE = new TypeToken<List<TimelinePoint>>(){}.getType();

    private static class TimelinePoint
    {
        long value;
        String date;
    }

    @Inject private OkHttpClient httpClient;
    @Inject private Gson gson;
    @Inject private DropHistoryManager manager;
    @Inject private DropHistoryConfig config;

    /** Records with a request in flight or already attempted this session. */
    private final Set<String> attempted = ConcurrentHashMap.newKeySet();

    /**
     * Asynchronously estimates the KC for a record with an unknown kill
     * count. Safe to call every frame; only the first call per record does
     * anything. On success the record is updated and persisted via
     * {@link DropHistoryManager#applyEstimate}.
     *
     * @param itemName item the record belongs to
     * @param record   the record with killCount == -1 and a usable timestamp
     * @param bossName collection log page title, used as the WOM boss metric
     * @param playerName the local player's display name
     */
    public void requestEstimate(String itemName, DropRecord record, String bossName, String playerName)
    {
        if (!config.womEstimates()
            || itemName == null || bossName == null || playerName == null
            || record.getKillCount() != -1 || record.getTimestamp() <= 0)
        {
            return;
        }

        String metric = toMetric(bossName);
        if (metric == null)
        {
            return;
        }

        String key = itemName.toLowerCase() + "|" + record.getTimestamp();
        if (!attempted.add(key))
        {
            return;
        }

        log.info("Requesting WOM KC estimate for {} ({}) as {}", itemName, metric, playerName);

        long dropTime = record.getTimestamp();
        HttpUrl url = HttpUrl.parse(WOM_API_BASE).newBuilder()
            .addPathSegment("players")
            .addPathSegment(playerName)
            .addPathSegment("snapshots")
            .addPathSegment("timeline")
            .addQueryParameter("metric", metric)
            .addQueryParameter("startDate", Instant.ofEpochMilli(dropTime - SNAPSHOT_WINDOW_MS).toString())
            .addQueryParameter("endDate", Instant.ofEpochMilli(dropTime + SNAPSHOT_WINDOW_MS).toString())
            .build();

        Request request = new Request.Builder()
            .url(url)
            .header("User-Agent", USER_AGENT)
            .build();

        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.info("WOM request failed for {}: {}", metric, e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody body = response.body())
                {
                    if (!response.isSuccessful() || body == null)
                    {
                        log.info("WOM returned {} for {} ({})", response.code(), playerName, metric);
                        return;
                    }
                    List<TimelinePoint> timeline = gson.fromJson(body.charStream(), TIMELINE_TYPE);
                    int estimate = interpolate(timeline, dropTime);
                    if (estimate > 0)
                    {
                        manager.applyEstimate(itemName, dropTime, estimate, bossName);
                        log.info("Estimated KC {} for {} via WOM ({})", estimate, itemName, metric);
                    }
                    else
                    {
                        log.info("No usable WOM snapshots for {} ({}) around the drop date", playerName, metric);
                    }
                }
                catch (Exception e)
                {
                    log.info("Failed to parse WOM response for {}", metric, e);
                }
            }
        });
    }

    /**
     * Linearly interpolates the KC at dropTime from the snapshots around it.
     * Returns -1 when no usable snapshots exist.
     */
    static int interpolate(List<TimelinePoint> timeline, long dropTime)
    {
        if (timeline == null || timeline.isEmpty())
        {
            return -1;
        }

        TimelinePoint before = null;
        TimelinePoint after = null;
        long beforeTime = 0;
        long afterTime = 0;

        for (TimelinePoint point : timeline)
        {
            if (point.value <= 0 || point.date == null)
            {
                continue;
            }
            long t;
            try
            {
                t = Instant.parse(point.date).toEpochMilli();
            }
            catch (Exception e)
            {
                continue;
            }
            if (t <= dropTime && (before == null || t > beforeTime))
            {
                before = point;
                beforeTime = t;
            }
            if (t >= dropTime && (after == null || t < afterTime))
            {
                after = point;
                afterTime = t;
            }
        }

        if (before != null && after != null)
        {
            if (afterTime == beforeTime)
            {
                return (int) before.value;
            }
            double fraction = (double) (dropTime - beforeTime) / (afterTime - beforeTime);
            return (int) Math.round(before.value + fraction * (after.value - before.value));
        }
        if (before != null)
        {
            return (int) before.value;
        }
        if (after != null)
        {
            return (int) after.value;
        }
        return -1;
    }

    /**
     * Maps a collection log page title to a WOM boss metric name, or null
     * if no mapping is likely. Unknown metrics fail harmlessly server-side.
     */
    static String toMetric(String bossName)
    {
        String name = bossName.toLowerCase().trim();
        String alias = METRIC_ALIASES.get(name);
        if (alias != null)
        {
            return alias;
        }
        String metric = name
            .replace("'", "")
            .replaceAll("[^a-z0-9]+", "_")
            .replaceAll("^_+|_+$", "");
        return metric.isEmpty() ? null : metric;
    }
}
